TRANSITIONS |= frozenset(('WARM_REVISIT_SCOPE_NOT_OWNED','WARM_REVISIT_PROTECTION_NOT_READY',
    'WARM_REVISIT_SOURCE_LEASE_LOST','WARM_REVISIT_CURRENT_AUTHORITY_LOST','WARM_REVISIT_OWNER_HEADROOM',
    'WARM_REVISIT_NO_WITNESSED_MINUTE','WARM_REVISIT_PREFIX_CANNOT_COMPLETE',
    'WARM_REVISIT_NATIVE_INPUTS_REFUSED'))
FIRST_GATES=(frozenset(SEED_HOLD.values())|frozenset(DENIAL.values())|
             frozenset(('ORIGINAL_CALLBACK_OBSERVED','NO_OBSERVED_OWNER_WIRE','NO_TIMELY_ORIGINAL_CALLBACK')))
BASE_FIELDS=frozenset(('schema','symbol','generation','end_ms','first_gate','owner_wire_charged_lanes',
                      'valid_reply_lanes','original_callbacks','observed_expiry_bound_ms','note','transition_ms'))
DETAIL_FIELDS=frozenset(('schema','symbol','generation','end_ms','kind','values'))
LANES=('15m','1m','5m')

def uint(n,hi):return type(n) is int and 0<=n<=hi
def member(s,known):return type(s) is str and s in known
def identity(d):
    s=d.get('symbol')
    return (type(s) is str and PATTERN.fullmatch(s) is not None
            and uint(d.get('generation'),2**63-1) and uint(d.get('end_ms'),2**63-1)
            and d['end_ms']>0 and d['end_ms']%Q==0)
def triplets(x,known,cap=None):
    if type(x) is not dict or not set(x)<=known or (cap is not None and len(x)>cap):return False
    for a in x.values():
        if (type(a) is not list or len(a)!=3 or not uint(a[0],TTL-1) or
            not uint(a[1],TTL-1) or not uint(a[2],255) or a[0]>a[1] or a[2]==0):return False
    return True
def lanes(x):
    return type(x) is list and all(member(v,LANES) for v in x) and x==sorted(set(x))
def accepted_symbol_event(d):
    if type(d) is not dict:return False
    if d.get('schema')=='c11-gate-readback-v1':
        return (set(d)==BASE_FIELDS and identity(d) and member(d['first_gate'],FIRST_GATES)
                and lanes(d['owner_wire_charged_lanes']) and lanes(d['valid_reply_lanes'])
                and uint(d['original_callbacks'],255) and uint(d['observed_expiry_bound_ms'],2**63-1)
                and d['end_ms']<=d['observed_expiry_bound_ms']<=d['end_ms']+TTL
                and d['note']=='FIRST_OBSERVATION_NOT_ROOT_CAUSE' and triplets(d['transition_ms'],TRANSITIONS,12))
    if d.get('schema')=='c11-gate-detail-v1':
        return (set(d)==DETAIL_FIELDS and identity(d)
                and member(d['kind'],EXTRA) and bool(d['values']) and triplets(d['values'],EXTRA[d['kind']][0]))
    return False
